const sources = [
  {
    source_name: 'Discover',
    source_url: 'https://www.discover.com/personal-loans/',
    product_name: 'Discover Personal Loan',
    income_currency: 'USD',
    extraction_profile: 'discover',
    allow_llm_fallback: false
  },
  {
    source_name: 'LendingPoint',
    source_url: 'https://www.lendingpoint.com/',
    product_name: 'LendingPoint Personal Loan',
    income_currency: 'USD',
    extraction_profile: 'lendingpoint',
    allow_llm_fallback: false
  },
  {
    source_name: 'Upgrade',
    source_url: 'https://www.upgrade.com/personal-loans/',
    product_name: 'Upgrade Personal Loan',
    income_currency: 'USD',
    extraction_profile: 'upgrade',
    allow_llm_fallback: false
  }
];

return sources.map((source) => ({ json: source }));

const source = $('Source configuration').item.json;

if ($json.error || typeof $json.html !== 'string' || !$json.html.trim()) {
  return {
    json: {
      ...source,
      status: 'failed',
      failure_stage: 'http_or_html',
      error_message: $json.error ? 'HTTP request failed' : 'Response did not contain HTML',
      llm_used: false
    }
  };
}

const decode = (value) => value
  .replace(/&nbsp;|&#160;/gi, ' ')
  .replace(/&amp;/gi, '&')
  .replace(/&quot;|&#34;/gi, '"')
  .replace(/&#39;|&apos;/gi, "'")
  .replace(/&lt;/gi, '<')
  .replace(/&gt;/gi, '>');

const text = decode(
  $json.html
    .replace(/<!--[\s\S]*?-->/g, ' ')
    .replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, ' ')
    .replace(/<style\b[^>]*>[\s\S]*?<\/style>/gi, ' ')
    .replace(/<noscript\b[^>]*>[\s\S]*?<\/noscript>/gi, ' ')
    .replace(/<[^>]+>/g, ' ')
    .replace(/\u200b/g, '')
    .replace(/\s+/g, ' ')
).trim();

if (text.length < 200) {
  return {
    json: {
      ...source,
      status: 'failed',
      failure_stage: 'html_cleanup',
      error_message: 'Cleaned page text was unexpectedly short',
      llm_used: false
    }
  };
}

const evidence = [];
const qualitative = [];
const addEvidence = (field, snippet) => {
  const clean = String(snippet || '').replace(/\s+/g, ' ').trim();
  if (clean && !evidence.some((entry) => entry.field === field && entry.snippet === clean)) {
    evidence.push({ field, snippet: clean.slice(0, 700) });
  }
};
const addQualitative = (criterion, snippet) => {
  if (!qualitative.includes(criterion)) qualitative.push(criterion);
  addEvidence('qualitative_criteria', snippet || criterion);
};
const rateMatch = text.match(/(\d{1,2}(?:\.\d{1,3})?)\s*%\s*(?:-|–|to)\s*(\d{1,2}(?:\.\d{1,3})?)\s*%\s*(?:APR)?/i);
const annualIncomeMatch = text.match(/minimum\s+(?:individual\s+or\s+household\s+)?annual\s+income\s+(?:of\s+)?(?:at\s+least\s+)?\$\s*([\d,]+)/i);
const ageMatch = text.match(/(?:(?:be\s+)?at\s+least\s+(\d{2})\s+years?(?:\s+of\s+age|\s+old))|(?:\bbe\s+)?(\d{2})\s+years?(?:\s+of\s+age)?\s+or\s+older/i);
const monthlyIncome = annualIncomeMatch
  ? Math.round((Number(annualIncomeMatch[1].replace(/,/g, '')) / 12) * 100) / 100
  : null;

let minInterestRate = rateMatch ? Number(rateMatch[1]) : null;
let maxInterestRate = rateMatch ? Number(rateMatch[2]) : null;
let minAge = ageMatch ? Number(ageMatch[1] || ageMatch[2]) : null;
let minMonthlyIncome = monthlyIncome;

if (rateMatch) addEvidence('interest_rate', rateMatch[0]);
if (annualIncomeMatch) addEvidence('minimum_monthly_income', annualIncomeMatch[0]);
if (ageMatch) addEvidence('age_min', ageMatch[0]);

if (source.extraction_profile === 'discover') {
  if (/valid\s+U\.?S\.?\s+SSN/i.test(text)) addQualitative('Valid U.S. Social Security number required', 'Have a valid U.S. SSN.');
  if (/physical\s+address/i.test(text)) addQualitative('Physical address required', 'Have a physical address.');
  if (/active\s+email\s+address/i.test(text)) addQualitative('Active email address and online-finalization access required', 'Have an active email address and access to a computer or mobile device to finalize the application online.');
}

if (source.extraction_profile === 'lendingpoint') {
  if (/government-issued\s+photo\s+ID/i.test(text)) addQualitative('Government-issued photo ID required', 'Be able to provide a U.S federal, state, or local government-issued photo ID.');
  if (/have\s+a\s+social\s+security\s+number/i.test(text)) addQualitative('Social Security number required', 'Have a social security number.');
  if (/verifiable\s+personal\s+banking\s+account/i.test(text)) addQualitative('Verifiable personal bank account required', 'Have a verifiable personal banking account in your name.');
  if (/not\s+reside\s+in\s+Nevada\s+or\s+West\s+Virginia/i.test(text)) addQualitative('Not available to Nevada or West Virginia residents', 'Not reside in Nevada or West Virginia.');
}

if (source.extraction_profile === 'upgrade') {
  if (/U\.?S\.?\s+citizen,?\s+a\s+permanent\s+resident,?\s+or\s+living\s+in\s+the\s+U\.?S\.?\s+on\s+a\s+valid\s+visa/i.test(text)) addQualitative('U.S. citizen, permanent resident, or valid U.S. visa required', 'Be a U.S. citizen, a permanent resident, or living in the U.S. on a valid visa.');
  if (/verifiable\s+bank\s+account\s+information/i.test(text)) addQualitative('Verifiable bank account information required', 'Be able to provide verifiable bank account information and a valid email address.');
  if (/credit\s+score,\s+credit\s+usage,\s+and\s+payment\s+history/i.test(text)) addQualitative('Credit score, credit usage, and payment history are considered', 'Eligibility for a loan through Upgrade is based on several factors, including your credit score, credit usage, and payment history.');
}

const snippetFor = (pattern) => {
  const found = text.search(pattern);
  if (found < 0) return '';
  return text.slice(Math.max(0, found - 350), Math.min(text.length, found + 1000));
};
const relevantText = [
  snippetFor(/APR/i),
  snippetFor(/eligib/i),
  snippetFor(/minimum\s+(?:individual\s+or\s+household\s+)?annual\s+income/i),
  snippetFor(/at\s+least\s+\d{2}\s+years?\s+old/i)
].filter(Boolean).filter((value, index, values) => values.indexOf(value) === index).join('\n---\n').slice(0, 6000);

const hasUnresolvedEligibilityText = /eligib|qualif|minimum\s+credit|credit\s+score|employment/i.test(relevantText)
  && qualitative.length === 0;

return {
  json: {
    ...source,
    status: 'extracted',
    min_interest_rate: minInterestRate,
    max_interest_rate: maxInterestRate,
    min_monthly_income: minMonthlyIncome,
    min_credit_score: null,
    max_credit_score: null,
    min_age: minAge,
    max_age: null,
    employment_statuses: null,
    qualitative_criteria: qualitative,
    source_evidence: evidence,
    relevant_text: relevantText,
    needs_llm: Boolean(source.allow_llm_fallback && hasUnresolvedEligibilityText),
    llm_used: false
  }
};

const nullable = (type) => ({ anyOf: [{ type }, { type: 'null' }] });
const profileSchema = {
  type: 'object',
  additionalProperties: false,
  properties: {
    product_name: { type: 'string' },
    min_interest_rate: nullable('number'),
    max_interest_rate: nullable('number'),
    min_monthly_income: nullable('number'),
    income_currency: nullable('string'),
    min_credit_score: nullable('integer'),
    max_credit_score: nullable('integer'),
    min_age: nullable('integer'),
    max_age: nullable('integer'),
    employment_statuses: { type: 'array', items: { type: 'string' } },
    qualitative_criteria: { type: 'array', items: { type: 'string' } },
    evidence: { type: 'array', items: { type: 'string' } }
  },
  required: [
    'product_name', 'min_interest_rate', 'max_interest_rate',
    'min_monthly_income', 'income_currency', 'min_credit_score',
    'max_credit_score', 'min_age', 'max_age', 'employment_statuses',
    'qualitative_criteria', 'evidence'
  ]
};

const instructions = [
  'Extract only eligibility facts explicitly supported by the supplied lender text.',
  'This is a normalization fallback, not a lending decision.',
  'Use null when a numeric field is absent, ambiguous, or only generally considered.',
  'Never infer a cutoff from marketing, examples, or typical lender practice.',
  'Only list employment statuses when the source explicitly states they are accepted or required.',
  'Keep unresolved requirements as concise qualitative_criteria strings.',
  'Every evidence item must be a short quotation or faithful excerpt from the supplied text.',
  'Return JSON only.'
].join(' ');

const llmRequest = {
  systemInstruction: {
    parts: [{ text: instructions }]
  },
  contents: [{
    role: 'user',
    parts: [{
      text: 'Source URL: ' + $json.source_url + '\nKnown product name: ' + $json.product_name + '\nCleaned eligibility/product excerpts only:\n' + $json.relevant_text
    }]
  }],
  generationConfig: {
    temperature: 0,
    maxOutputTokens: 2048,
    responseMimeType: 'application/json',
    responseJsonSchema: profileSchema,
    thinkingConfig: { thinkingBudget: 0 }
  }
};

return { json: { ...$json, llm_request: llmRequest } };

const original = $('Build scoped LLM request').item.json;

if ($json.error) {
  return {
    json: {
      ...original,
      status: 'failed',
      failure_stage: 'llm_request',
      error_message: 'LLM request failed',
      llm_used: true
    }
  };
}

function responseText(payload) {
  const body = payload && payload.candidates ? payload : ((payload && (payload.body || payload.data)) || {});
  const parts = body.candidates && body.candidates[0] && body.candidates[0].content
    ? body.candidates[0].content.parts || []
    : [];
  return parts.filter((part) => part && !part.thought).map((part) => part.text || '').join('');
}

const content = responseText($json).trim().replace(/^```json\s*|```$/g, '');
let extracted;
try {
  extracted = content ? JSON.parse(content) : null;
} catch (error) {
  extracted = null;
}

if (!extracted || typeof extracted !== 'object' || Array.isArray(extracted)) {
  return {
    json: {
      ...original,
      status: 'failed',
      failure_stage: 'llm_parse',
      error_message: 'LLM response did not contain a JSON object matching the requested profile',
      llm_used: true
    }
  };
}

const numericFields = [
  'min_interest_rate', 'max_interest_rate', 'min_monthly_income',
  'min_credit_score', 'max_credit_score', 'min_age', 'max_age'
];
for (const field of numericFields) {
  if (extracted[field] !== null && !Number.isFinite(extracted[field])) {
    return {
      json: {
        ...original,
        status: 'failed',
        failure_stage: 'llm_validation',
        error_message: 'LLM returned a non-numeric value for ' + field,
        llm_used: true
      }
    };
  }
}
if (!Array.isArray(extracted.employment_statuses) || !Array.isArray(extracted.qualitative_criteria) || !Array.isArray(extracted.evidence)) {
  return {
    json: {
      ...original,
      status: 'failed',
      failure_stage: 'llm_validation',
      error_message: 'LLM returned an invalid array field',
      llm_used: true
    }
  };
}

const filledOnlyWhenUnknown = {};
for (const field of numericFields) {
  filledOnlyWhenUnknown[field] = original[field] === null && extracted[field] !== null
    ? extracted[field]
    : original[field];
}
const sourceEvidence = [
  ...(original.source_evidence || []),
  ...extracted.evidence.filter((value) => typeof value === 'string' && value.trim()).map((snippet) => ({
    field: 'llm_eligibility',
    snippet: snippet.trim().slice(0, 700)
  }))
];

return {
  json: {
    ...original,
    ...filledOnlyWhenUnknown,
    income_currency: original.income_currency || extracted.income_currency || null,
    employment_statuses: original.employment_statuses === null && extracted.employment_statuses.length ? extracted.employment_statuses : original.employment_statuses,
    qualitative_criteria: [...new Set([...(original.qualitative_criteria || []), ...extracted.qualitative_criteria.filter((value) => typeof value === 'string' && value.trim())])],
    source_evidence: sourceEvidence,
    status: 'extracted',
    llm_used: true
  }
};

const profile = { ...$json };

if (profile.status === 'failed') {
  return { json: { ...profile, valid: false } };
}

const numericFields = [
  'min_interest_rate', 'max_interest_rate', 'min_monthly_income',
  'min_credit_score', 'max_credit_score', 'min_age', 'max_age'
];
const fieldRange = {
  min_interest_rate: [0, 100],
  max_interest_rate: [0, 100],
  min_monthly_income: [0, 100000000],
  min_credit_score: [0, 1000],
  max_credit_score: [0, 1000],
  min_age: [0, 130],
  max_age: [0, 130]
};
for (const field of numericFields) {
  const value = profile[field];
  if (value === null || value === undefined) {
    profile[field] = null;
    continue;
  }
  if (!Number.isFinite(value) || value < fieldRange[field][0] || value > fieldRange[field][1]) {
    return {
      json: {
        ...profile,
        status: 'failed',
        failure_stage: 'profile_validation',
        error_message: 'Out-of-range or non-numeric ' + field,
        valid: false
      }
    };
  }
}
if ((profile.min_interest_rate !== null && profile.max_interest_rate !== null && profile.min_interest_rate > profile.max_interest_rate) ||
    (profile.min_credit_score !== null && profile.max_credit_score !== null && profile.min_credit_score > profile.max_credit_score) ||
    (profile.min_age !== null && profile.max_age !== null && profile.min_age > profile.max_age)) {
  return {
    json: {
      ...profile,
      status: 'failed',
      failure_stage: 'profile_validation',
      error_message: 'A normalized minimum exceeds its maximum',
      valid: false
    }
  };
}
if (typeof profile.product_name !== 'string' || !profile.product_name.trim() || typeof profile.source_name !== 'string' || !/^https:\/\//.test(profile.source_url || '')) {
  return {
    json: {
      ...profile,
      status: 'failed',
      failure_stage: 'profile_validation',
      error_message: 'Missing stable product or source identity',
      valid: false
    }
  };
}
if (typeof profile.income_currency !== 'string' || !/^[A-Z]{3}$/.test(profile.income_currency)) {
  return {
    json: {
      ...profile,
      status: 'failed',
      failure_stage: 'profile_validation',
      error_message: 'Income currency must be an ISO-4217 style uppercase code',
      valid: false
    }
  };
}

const employmentAliases = {
  'salaried employee': 'salaried',
  'salaried': 'salaried',
  'employed': 'salaried',
  'self employed': 'self_employed',
  'self-employed': 'self_employed',
  'business owner': 'self_employed',
  'retired': 'retired',
  'unemployed': 'unemployed',
  'student': 'student',
  'contractor': 'contract',
  'contract': 'contract'
};
const normalizeEmployment = (value) => employmentAliases[String(value).trim().toLowerCase()] || null;
const statuses = Array.isArray(profile.employment_statuses)
  ? [...new Set(profile.employment_statuses.map(normalizeEmployment).filter(Boolean))]
  : [];
profile.employment_statuses = statuses.length ? statuses : null;
profile.qualitative_criteria = Array.isArray(profile.qualitative_criteria)
  ? [...new Set(profile.qualitative_criteria.map((value) => String(value).replace(/\s+/g, ' ').trim()).filter(Boolean))]
  : [];
profile.source_evidence = Array.isArray(profile.source_evidence)
  ? profile.source_evidence.filter((entry) => entry && typeof entry.field === 'string' && typeof entry.snippet === 'string' && entry.snippet.trim()).map((entry) => ({
      field: entry.field,
      snippet: entry.snippet.replace(/\s+/g, ' ').trim().slice(0, 700)
    }))
  : [];
delete profile.relevant_text;
delete profile.llm_request;
delete profile.allow_llm_fallback;
delete profile.extraction_profile;
delete profile.needs_llm;

return { json: { ...profile, valid: true } };

const profile = $('Validate normalized profile').item.json;
if ($json.error) {
  return {
    json: {
      outcome: 'failure',
      source_name: profile.source_name,
      product_name: profile.product_name,
      failure_stage: 'database',
      error_message: 'PostgreSQL upsert failed',
      llm_used: Boolean(profile.llm_used)
    }
  };
}
return {
  json: {
    outcome: 'upserted',
    source_name: profile.source_name,
    product_name: profile.product_name,
    product_id: $json.id,
    llm_used: Boolean(profile.llm_used)
  }
};

return {
  json: {
    outcome: 'failure',
    source_name: $json.source_name || 'unknown',
    product_name: $json.product_name || 'unknown',
    failure_stage: $json.failure_stage || 'profile_validation',
    error_message: $json.error_message || 'Profile was not safe to persist',
    llm_used: Boolean($json.llm_used)
  }
};

const outcomes = $input.all().map((item) => item.json);
const summary = {
  sources_processed: outcomes.length,
  products_extracted: outcomes.filter((item) => item.outcome === 'upserted').length,
  products_upserted: outcomes.filter((item) => item.outcome === 'upserted').length,
  llm_extractions: outcomes.filter((item) => item.llm_used).length,
  extraction_failures: outcomes.filter((item) => item.outcome === 'failure').length,
  failures: outcomes.filter((item) => item.outcome === 'failure').map((item) => ({
    source_name: item.source_name,
    stage: item.failure_stage,
    error: item.error_message
  }))
};
return [{ json: summary }];

const configuredSources = $('Source configuration').all().map((item) => ({
  source_name: item.json.source_name,
  source_url: item.json.source_url,
  product_name: item.json.product_name,
}));
const summary = $input.first().json;
return [{
  json: {
    ...summary,
    configured_sources: configuredSources,
  },
}];

const summary = $('Prepare deactivation input').first().json;
const { configured_sources, ...publicSummary } = summary;
return {
  json: {
    ...publicSummary,
    products_deactivated: Number($json.products_deactivated || 0),
  },
};
